1	package server
2	
3	import (
4		"encoding/json"
5		"io"
6		"maps"
7		"mime"
8		"net/http"
9		"net/url"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	const (
16		spansPath            = "/api/v1/spans"
17		tracesCollectionPath = "/api/v1/traces"
18		tracesPrefix         = tracesCollectionPath + "/"
19	)
20	
21	var spanStatuses = map[string]bool{
22		"unset": true,
23		"ok":    true,
24		"error": true,
25	}
26	
27	// span is one committed trace span. Spans are immutable once stored.
28	type span struct {
29		traceID      string
30		spanID       string
31		parentSpanID string // "" when parent_span_id is null
32		service      string
33		name         string
34		startTime    time.Time
35		endTime      time.Time
36		status       string
37		attributes   map[string]string
38	}
39	
40	// sameContent reports whether two spans with the same (trace_id, span_id)
41	// carry the same content, making the later one a replay rather than a
42	// conflict. Time instants compare regardless of the submitted zone.
43	func (sp *span) sameContent(other *span) bool {
44		return sp.traceID == other.traceID &&
45			sp.spanID == other.spanID &&
46			sp.parentSpanID == other.parentSpanID &&
47			sp.service == other.service &&
48			sp.name == other.name &&
49			sp.startTime.Equal(other.startTime) &&
50			sp.endTime.Equal(other.endTime) &&
51			sp.status == other.status &&
52			maps.Equal(sp.attributes, other.attributes)
53	}
54	
55	// spanKey builds the tenant-unique identity of a span from trace and span id.
56	// Both ids are lowercase hex of fixed length, so a NUL separator is
57	// unambiguous.
58	func spanKey(traceID, spanID string) string {
59		return traceID + "\x00" + spanID
60	}
61	
62	// checkAndApplySpans validates the batch against committed state (and against
63	// itself) and then commits it in array order. A false ok signals a content
64	// conflict on a repeated span; in that case no state is mutated. Replays —
65	// repeats of a (trace_id, span_id) with identical content — are counted but
66	// do not mutate state. Conflict and replay detection always runs before
67	// sampling: only spans not yet retained are subject to the tenant's sampling
68	// policy, decided on the trace id at trace_rate so a trace's spans and traced
69	// logs are kept or dropped together. Dropped spans leave no trace.
70	// sampling reports whether the policy in effect had any rate below 1, so the
71	// response can carry sampled_out.
72	func (s *metricStore) checkAndApplySpans(batch []*span) (accepted, replayed, sampledOutN int, sampling, ok bool) {
73		s.mu.Lock()
74		defer s.mu.Unlock()
75	
76		// First pass: conflict detection against committed spans and earlier
77		// spans in the same batch.
78		seen := make(map[string]*span, len(batch))
79		for _, sp := range batch {
80			key := spanKey(sp.traceID, sp.spanID)
81			if prev, dup := seen[key]; dup {
82				if !prev.sameContent(sp) {
83					return 0, 0, 0, false, false
84				}
85				continue
86			}
87			if existing, committed := s.spans[key]; committed && !existing.sameContent(sp) {
88				return 0, 0, 0, false, false
89			}
90			seen[key] = sp
91		}
92	
93		// Second pass: commit in array order.
94		policy := s.sampling
95		sampling = policy.active()
96		for _, sp := range batch {
97			key := spanKey(sp.traceID, sp.spanID)
98			if _, exists := s.spans[key]; exists {
99				replayed++
100				continue
101			}
102			if sampledOut(sp.traceID, policy.TraceRate) {
103				sampledOutN++
104				continue
105			}
106			s.spans[key] = sp
107			accepted++
108		}
109		return accepted, replayed, sampledOutN, sampling, true
110	}
111	
112	// traceSnapshot is one consistent read of a trace's spans together with the
113	// retained logs carrying the same trace id.
114	type traceSnapshot struct {
115		spans []*span
116		logs  []*logEntry
117	}
118	
119	// getTrace returns the spans of traceID and the currently retained logs with
120	// that trace id. The found flag is false only when no span is stored; logs
121	// alone never create a trace.
122	func (s *metricStore) getTrace(traceID string) (traceSnapshot, bool) {
123		s.mu.RLock()
124		defer s.mu.RUnlock()
125	
126		var snap traceSnapshot
127		for _, sp := range s.spans {
128			if sp.traceID == traceID {
129				snap.spans = append(snap.spans, sp)
130			}
131		}
132		if len(snap.spans) == 0 {
133			return traceSnapshot{}, false
134		}
135		for _, e := range s.logs {
136			if e.traceID == traceID {
137				snap.logs = append(snap.logs, e)
138			}
139		}
140		sort.Slice(snap.spans, func(i, j int) bool {
141			a, b := snap.spans[i], snap.spans[j]
142			if !a.startTime.Equal(b.startTime) {
143				return a.startTime.Before(b.startTime)
144			}
145			return a.spanID < b.spanID
146		})
147		sort.Slice(snap.logs, func(i, j int) bool {
148			a, b := snap.logs[i], snap.logs[j]
149			if !a.timestamp.Equal(b.timestamp) {
150				return a.timestamp.Before(b.timestamp)
151			}
152			return a.id < b.id
153		})
154		return snap, true
155	}
156	
157	// ---- JSON wire shapes ------------------------------------------------------
158	
159	type spansEnvelope struct {
160		Spans *[]json.RawMessage `json:"spans"`
161	}
162	
163	type rawSpan struct {
164		TraceID      *string         `json:"trace_id"`
165		SpanID       *string         `json:"span_id"`
166		ParentSpanID json.RawMessage `json:"parent_span_id"`
167		Service      *string         `json:"service"`
168		Name         *string         `json:"name"`
169		StartTime    *string         `json:"start_time"`
170		EndTime      *string         `json:"end_time"`
171		Status       *string         `json:"status"`
172		Attributes   json.RawMessage `json:"attributes"`
173	}
174	
175	type spanJSON struct {
176		TraceID      string            `json:"trace_id"`
177		SpanID       string            `json:"span_id"`
178		ParentSpanID *string           `json:"parent_span_id"`
179		Service      string            `json:"service"`
180		Name         string            `json:"name"`
181		StartTime    string            `json:"start_time"`
182		EndTime      string            `json:"end_time"`
183		Status       string            `json:"status"`
184		Attributes   map[string]string `json:"attributes"`
185	}
186	
187	func (sp *span) wireJSON() spanJSON {
188		out := spanJSON{
189			TraceID:    sp.traceID,
190			SpanID:     sp.spanID,
191			Service:    sp.service,
192			Name:       sp.name,
193			StartTime:  sp.startTime.UTC().Format(time.RFC3339Nano),
194			EndTime:    sp.endTime.UTC().Format(time.RFC3339Nano),
195			Status:     sp.status,
196			Attributes: copyLabels(sp.attributes),
197		}
198		if sp.parentSpanID != "" {
199			parent := sp.parentSpanID
200			out.ParentSpanID = &parent
201		}
202		return out
203	}
204	
205	// decodeSpanBatch performs every format and value check. It never returns a
206	// partially validated batch.
207	func decodeSpanBatch(body []byte) ([]*span, bool) {
208		var env spansEnvelope
209		if !strictDecode(body, &env) || env.Spans == nil || len(*env.Spans) == 0 {
210			return nil, false
211		}
212	
213		batch := make([]*span, 0, len(*env.Spans))
214		for _, raw := range *env.Spans {
215			var rs rawSpan
216			if !strictDecode(raw, &rs) {
217				return nil, false
218			}
219			if rs.TraceID == nil || rs.SpanID == nil || len(rs.ParentSpanID) == 0 ||
220				rs.Service == nil || rs.Name == nil || rs.StartTime == nil ||
221				rs.EndTime == nil || rs.Status == nil || rs.Attributes == nil {
222				return nil, false
223			}
224			traceID := *rs.TraceID
225			if !validTraceID(traceID) {
226				return nil, false
227			}
228			spanID := *rs.SpanID
229			if !validSpanID(spanID) {
230				return nil, false
231			}
232			// parent_span_id is exactly null or a span-id string; a missing field
233			// was rejected above. The parent span itself may arrive later.
234			var parentPtr *string
235			if err := json.Unmarshal(rs.ParentSpanID, &parentPtr); err != nil {
236				return nil, false
237			}
238			parentSpanID := ""
239			if parentPtr != nil {
240				parentSpanID = *parentPtr
241				if !validSpanID(parentSpanID) || parentSpanID == spanID {
242					return nil, false
243				}
244			}
245			service := *rs.Service
246			name := *rs.Name
247			if service == "" || name == "" {
248				return nil, false
249			}
250			startTime, err := time.Parse(time.RFC3339Nano, *rs.StartTime)
251			if err != nil {
252				return nil, false
253			}
254			endTime, err := time.Parse(time.RFC3339Nano, *rs.EndTime)
255			if err != nil {
256				return nil, false
257			}
258			if endTime.Before(startTime) {
259				return nil, false
260			}
261			status := *rs.Status
262			if !spanStatuses[status] {
263				return nil, false
264			}
265			// attributes must be a JSON object of string values. RawMessage keeps
266			// explicit nulls visible: encoding/json would otherwise fold a null
267			// value into the empty string, and a whole-document null into a nil
268			// map; both are illegal here.
269			var rawAttrs map[string]json.RawMessage
270			if err := json.Unmarshal(rs.Attributes, &rawAttrs); err != nil || rawAttrs == nil {
271				return nil, false
272			}
273			attributes := make(map[string]string, len(rawAttrs))
274			for k, rawVal := range rawAttrs {
275				if !identPattern.MatchString(k) {
276					return nil, false
277				}
278				var value *string
279				if err := json.Unmarshal(rawVal, &value); err != nil || value == nil {
280					return nil, false
281				}
282				attributes[k] = *value
283			}
284			batch = append(batch, &span{
285				traceID:      traceID,
286				spanID:       spanID,
287				parentSpanID: parentSpanID,
288				service:      service,
289				name:         name,
290				startTime:    startTime,
291				endTime:      endTime,
292				status:       status,
293				attributes:   attributes,
294			})
295		}
296		return batch, true
297	}
298	
299	// validSpanID reports whether id is exactly 16 lowercase hex characters.
300	func validSpanID(id string) bool {
301		if len(id) != 16 {
302			return false
303		}
304		for i := 0; i < len(id); i++ {
305			c := id[i]
306			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
307				return false
308			}
309		}
310		return true
311	}
312	
313	// ---- HTTP handlers ---------------------------------------------------------
314	
315	func registerSpanHandlers(mux *http.ServeMux) {
316		mux.HandleFunc(spansPath, func(w http.ResponseWriter, r *http.Request) {
317			if r.Method != http.MethodPost {
318				w.Header().Set("Allow", http.MethodPost)
319				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
320				return
321			}
322			handleSpansPost(w, r)
323		})
324	
325		// The trace collection has no list endpoint; answer the exact collection
326		// path with the baseline 404 instead of letting the subtree pattern issue
327		// its trailing-slash redirect.
328		mux.HandleFunc(tracesCollectionPath, func(w http.ResponseWriter, r *http.Request) {
329			http.NotFound(w, r)
330		})
331	
332		mux.HandleFunc(tracesPrefix, func(w http.ResponseWriter, r *http.Request) {
333			if r.Method != http.MethodGet {
334				w.Header().Set("Allow", http.MethodGet)
335				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
336				return
337			}
338			handleTraceGet(w, r)
339		})
340	}
341	
342	func handleSpansPost(w http.ResponseWriter, r *http.Request) {
343		store := tenantStore(r)
344		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
345		if err != nil || mediaType != "application/json" {
346			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
347			return
348		}
349	
350		body, err := io.ReadAll(r.Body)
351		if err != nil {
352			writeAPIError(w, "invalid_spans", http.StatusBadRequest)
353			return
354		}
355	
356		batch, ok := decodeSpanBatch(body)
357		if !ok {
358			writeAPIError(w, "invalid_spans", http.StatusBadRequest)
359			return
360		}
361	
362		accepted, replayed, sampledOutN, sampling, applied := store.checkAndApplySpans(batch)
363		if !applied {
364			writeAPIError(w, "span_conflict", http.StatusConflict)
365			return
366		}
367	
368		resp := map[string]int{"accepted": accepted, "replayed": replayed}
369		if sampling {
370			resp["sampled_out"] = sampledOutN
371		}
372		writeJSON(w, http.StatusAccepted, resp)
373	}
374	
375	func handleTraceGet(w http.ResponseWriter, r *http.Request) {
376		traceID := strings.TrimPrefix(r.URL.Path, tracesPrefix)
377		if traceID == "" || strings.Contains(traceID, "/") || !validTraceID(traceID) {
378			writeAPIError(w, "invalid_trace_id", http.StatusBadRequest)
379			return
380		}
381		// The trace detail endpoint defines no query vocabulary, so any parameter
382		// is an invalid query.
383		values, err := url.ParseQuery(r.URL.RawQuery)
384		if err != nil || len(values) != 0 {
385			writeAPIError(w, "invalid_trace_query", http.StatusBadRequest)
386			return
387		}
388	
389		snap, found := tenantStore(r).getTrace(traceID)
390		if !found {
391			writeAPIError(w, "trace_not_found", http.StatusNotFound)
392			return
393		}
394	
395		spans := make([]spanJSON, 0, len(snap.spans))
396		for _, sp := range snap.spans {
397			spans = append(spans, sp.wireJSON())
398		}
399		logs := make([]logEntryJSON, 0, len(snap.logs))
400		for _, e := range snap.logs {
401			logs = append(logs, e.wireJSON())
402		}
403		writeJSON(w, http.StatusOK, map[string]any{
404			"trace_id": traceID,
405			"spans":    spans,
406			"logs":     logs,
407		})
408	}
