1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21		"time"
22	)
23	
24	// Version is the baseline release identifier.
25	const Version = "0.1.0"
26	
27	const metricsPath = "/api/v1/metrics"
28	
29	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
30	
31	type health struct {
32		Status  string `json:"status"`
33		Service string `json:"service"`
34		Version string `json:"version"`
35	}
36	
37	// series is one uniquely identified time series: name + full label set.
38	type series struct {
39		name   string
40		typ    string
41		labels map[string]string
42	
43		// counter/gauge state
44		value float64
45	
46		// histogram state
47		bucketBounds []float64 // strictly increasing, fixed at first write
48		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
49		count        int64
50		sum          float64
51	
52		// history holds accepted samples in commit order for range queries.
53		// Entries older than the retention window are ignored at query time;
54		// evicting them never touches the cumulative state above.
55		history []historyPoint
56	}
57	
58	type metricStore struct {
59		mu     sync.RWMutex
60		series map[string]*series
61	
62		// alert rules keyed by rule id; guarded by mu so rule replacement and
63		// alert evaluation are atomic with metric commits.
64		rules map[string]*alertRule
65	
66		// silences keyed by silence id; same lock so alert evaluation reads
67		// metrics, rules and silences from one consistent snapshot.
68		silences map[string]*silence
69	
70		// inhibit rules keyed by rule id; same lock so alert evaluation also
71		// reads inhibit rules from the same consistent snapshot.
72		inhibitions map[string]*inhibitRule
73	
74		// notification routes keyed by route id; same lock so the notification
75		// plan reads routes from the same snapshot as alert evaluation.
76		notificationRoutes map[string]*notificationRoute
77	
78		// SLO definitions keyed by SLO id; same lock so status evaluation reads
79		// definitions and counters from one consistent snapshot.
80		slos map[string]*sloDefinition
81	
82		// Log entries keyed by entry id; same lock so log commits and retrieval
83		// read one consistent snapshot. logOrder is the submission-order FIFO
84		// of ids used for eviction; logSeq is the commit sequence that anchors
85		// paginated read snapshots.
86		logs     map[string]*logEntry
87		logOrder []string
88		logSeq   int64
89	
90		// Spans keyed by tenant-unique "trace_id\x00span_id"; same lock so span
91		// commits and trace reads share the logs snapshot they join against.
92		spans map[string]*span
93	
94		// Deterministic ingest sampling policy; same lock so a policy swap is
95		// atomic with respect to the log/span commits it governs.
96		sampling samplingPolicy
97	
98		// Discovery target snapshot; same lock so reloads swap one immutable
99		// snapshot pointer and queries always read a consistent generation.
100		discovery *discoverySnapshot
101	
102		// scrapeBaseline holds the last committed cumulative counter value per
103		// scraped series key; same lock so a target's batch and its baseline
104		// update commit atomically.
105		scrapeBaseline map[string]float64
106	}
107	
108	func newMetricStore() *metricStore {
109		return &metricStore{
110			series:             make(map[string]*series),
111			rules:              make(map[string]*alertRule),
112			silences:           make(map[string]*silence),
113			inhibitions:        make(map[string]*inhibitRule),
114			notificationRoutes: make(map[string]*notificationRoute),
115			slos:               make(map[string]*sloDefinition),
116			logs:               make(map[string]*logEntry),
117			spans:              make(map[string]*span),
118			sampling:           defaultSamplingPolicy(),
119			discovery:          emptyDiscoverySnapshot(),
120			scrapeBaseline:     make(map[string]float64),
121		}
122	}
123	
124	// validatedSample is a sample that passed all format and value checks.
125	type validatedSample struct {
126		key     string
127		name    string
128		typ     string
129		labels  map[string]string
130		value   float64
131		buckets []float64 // non-nil for histograms
132		ts      time.Time
133	}
134	
135	// checkAndApply validates the batch against the current state (and against
136	// itself) and then commits it in array order. A false result signals a type or
137	// bucket-boundary conflict; in that case no state is mutated.
138	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
139		s.mu.Lock()
140		defer s.mu.Unlock()
141	
142		// First pass: conflict detection against committed state and earlier
143		// samples in the same batch.
144		resolved := make(map[string]*series, len(batch))
145		for _, sm := range batch {
146			existing, ok := s.series[sm.key]
147			if !ok {
148				if shadow, seen := resolved[sm.key]; seen {
149					existing, ok = shadow, true
150				}
151			}
152			if ok {
153				if existing.typ != sm.typ {
154					return false
155				}
156				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
157					return false
158				}
159				resolved[sm.key] = existing
160				continue
161			}
162			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
163		}
164	
165		// Second pass: commit in order.
166		for _, sm := range batch {
167			cur, ok := s.series[sm.key]
168			if !ok {
169				cur = &series{
170					name:         sm.name,
171					typ:          sm.typ,
172					labels:       sm.labels,
173					bucketBounds: append([]float64(nil), sm.buckets...),
174				}
175				if sm.typ == "histogram" {
176					cur.bucketCounts = make([]int64, len(sm.buckets))
177				}
178				s.series[sm.key] = cur
179			}
180			switch sm.typ {
181			case "counter":
182				cur.value += sm.value
183			case "gauge":
184				cur.value = sm.value
185			case "histogram":
186				cur.count++
187				cur.sum += sm.value
188				for i, bound := range cur.bucketBounds {
189					if sm.value <= bound {
190						cur.bucketCounts[i]++
191					}
192				}
193			}
194			cur.history = append(cur.history, historyPoint{ts: sm.ts, value: sm.value})
195		}
196		return true
197	}
198	
199	type seriesOutput struct {
200		Name    string            `json:"name"`
201		Type    string            `json:"type"`
202		Labels  map[string]string `json:"labels"`
203		Value   *float64          `json:"value,omitempty"`
204		Count   *int64            `json:"count,omitempty"`
205		Sum     *float64          `json:"sum,omitempty"`
206		Buckets []bucketOutput    `json:"buckets,omitempty"`
207	}
208	
209	type bucketOutput struct {
210		LE    float64 `json:"le"`
211		Count int64   `json:"count"`
212	}
213	
214	// query returns matching series as ready-to-encode outputs. A series matches
215	// when its name equals name exactly and it contains every selector label.
216	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
217		s.mu.RLock()
218		defer s.mu.RUnlock()
219	
220		out := make([]seriesOutput, 0)
221		for _, cur := range s.series {
222			if cur.name != name {
223				continue
224			}
225			matched := true
226			for k, v := range selector {
227				got, ok := cur.labels[k]
228				if !ok || got != v {
229					matched = false
230					break
231				}
232			}
233			if !matched {
234				continue
235			}
236			item := seriesOutput{
237				Name:   cur.name,
238				Type:   cur.typ,
239				Labels: copyLabels(cur.labels),
240			}
241			switch cur.typ {
242			case "counter", "gauge":
243				v := cur.value
244				item.Value = &v
245			case "histogram":
246				c, sum := cur.count, cur.sum
247				item.Count = &c
248				item.Sum = &sum
249				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
250				for i, bound := range cur.bucketBounds {
251					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
252				}
253			}
254			out = append(out, item)
255		}
256	
257		sort.Slice(out, func(i, j int) bool {
258			return compareLabels(out[i].Labels, out[j].Labels) < 0
259		})
260		return out
261	}
262	
263	// compareLabels imposes a normalized lexicographic order on full label sets:
264	// keys are sorted, then (key, value) pairs are compared element-wise, and a
265	// shorter pair list sorts first when it is a prefix of a longer one.
266	func compareLabels(a, b map[string]string) int {
267		ka := sortedKeys(a)
268		kb := sortedKeys(b)
269		n := len(ka)
270		if len(kb) < n {
271			n = len(kb)
272		}
273		for i := 0; i < n; i++ {
274			if ka[i] != kb[i] {
275				return strings.Compare(ka[i], kb[i])
276			}
277			if a[ka[i]] != b[kb[i]] {
278				return strings.Compare(a[ka[i]], b[kb[i]])
279			}
280		}
281		switch {
282		case len(ka) < len(kb):
283			return -1
284		case len(ka) > len(kb):
285			return 1
286		default:
287			return 0
288		}
289	}
290	
291	func sortedKeys(m map[string]string) []string {
292		keys := make([]string, 0, len(m))
293		for k := range m {
294			keys = append(keys, k)
295		}
296		sort.Strings(keys)
297		return keys
298	}
299	
300	func copyLabels(in map[string]string) map[string]string {
301		out := make(map[string]string, len(in))
302		for k, v := range in {
303			out[k] = v
304		}
305		return out
306	}
307	
308	// seriesKey builds a collision-free identity from name + unordered labels.
309	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
310	// so length-prefixed values remove any ambiguity from arbitrary label values.
311	func seriesKey(name string, labels map[string]string) string {
312		var b strings.Builder
313		b.WriteString(name)
314		for _, k := range sortedKeys(labels) {
315			b.WriteByte(0)
316			b.WriteString(k)
317			b.WriteByte(0)
318			v := labels[k]
319			b.WriteString(strconv.Itoa(len(v)))
320			b.WriteByte(0)
321			b.WriteString(v)
322		}
323		return b.String()
324	}
325	
326	func equalBuckets(a, b []float64) bool {
327		if len(a) != len(b) {
328			return false
329		}
330		for i := range a {
331			if a[i] != b[i] {
332				return false
333			}
334		}
335		return true
336	}
337	
338	// Handler returns the HTTP surface served by SignalWatch.
339	func Handler() http.Handler {
340		return newHandler(newTenantRegistry())
341	}
342	
343	func newHandler(registry *tenantRegistry) http.Handler {
344		mux := http.NewServeMux()
345	
346		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
347			if r.Method != http.MethodGet {
348				w.Header().Set("Allow", http.MethodGet)
349				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
350				return
351			}
352			w.Header().Set("Content-Type", "application/json; charset=utf-8")
353			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
354		})
355	
356		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
357			switch r.Method {
358			case http.MethodGet:
359				handleMetricsGet(w, r)
360			case http.MethodPost:
361				handleMetricsPost(w, r)
362			default:
363				w.Header().Set("Allow", "GET, POST")
364				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
365			}
366		})
367	
368		registerAlertHandlers(mux)
369		registerSilenceHandlers(mux)
370		registerInhibitHandlers(mux)
371		registerNotificationRouteHandlers(mux)
372		registerSLOHandlers(mux)
373		registerQueryHandler(mux)
374		registerMetricRangeHandler(mux)
375		registerQueryRangeHandler(mux)
376		registerLogHandlers(mux)
377		registerSpanHandlers(mux)
378		registerSamplingPolicyHandlers(mux)
379		registerDiscoveryTargetHandlers(mux)
380	
381		return withTenants(mux, registry)
382	}
383	
384	func handleMetricsPost(w http.ResponseWriter, r *http.Request) {
385		// All samples in the request share this single receive instant: it is the
386		// default timestamp and the anchor for the accepted timestamp window.
387		receivedAt := time.Now()
388		store := tenantStore(r)
389		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
390		if err != nil || mediaType != "application/json" {
391			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
392			return
393		}
394	
395		body, err := io.ReadAll(r.Body)
396		if err != nil {
397			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
398			return
399		}
400	
401		batch, code := decodeMetricsBatch(body, receivedAt)
402		if code != "" {
403			writeAPIError(w, code, http.StatusBadRequest)
404			return
405		}
406	
407		if !store.checkAndApply(batch) {
408			writeAPIError(w, "metric_conflict", http.StatusConflict)
409			return
410		}
411	
412		w.Header().Set("Content-Type", "application/json; charset=utf-8")
413		w.WriteHeader(http.StatusAccepted)
414		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
415	}
416	
417	type metricsEnvelope struct {
418		Samples *[]json.RawMessage `json:"samples"`
419	}
420	
421	type rawSample struct {
422		Name      *string            `json:"name"`
423		Type      *string            `json:"type"`
424		Labels    *map[string]string `json:"labels"`
425		Value     *float64           `json:"value"`
426		Buckets   *[]float64         `json:"buckets"`
427		Timestamp *string            `json:"timestamp"`
428	}
429	
430	// decodeMetricsBatch performs every format and value check, including the
431	// optional per-sample timestamp. It never returns a partially validated
432	// batch. The returned error code is empty on success.
433	func decodeMetricsBatch(body []byte, receivedAt time.Time) ([]validatedSample, string) {
434		var env metricsEnvelope
435		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
436			return nil, "invalid_metrics"
437		}
438	
439		batch := make([]validatedSample, 0, len(*env.Samples))
440		for _, raw := range *env.Samples {
441			var sm rawSample
442			if !strictDecode(raw, &sm) {
443				return nil, "invalid_metrics"
444			}
445			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
446				return nil, "invalid_metrics"
447			}
448			name, typ := *sm.Name, *sm.Type
449			if !identPattern.MatchString(name) {
450				return nil, "invalid_metrics"
451			}
452			if typ != "counter" && typ != "gauge" && typ != "histogram" {
453				return nil, "invalid_metrics"
454			}
455			labels := *sm.Labels
456			if labels == nil {
457				return nil, "invalid_metrics" // explicit null labels
458			}
459			for k := range labels {
460				if !identPattern.MatchString(k) {
461					return nil, "invalid_metrics"
462				}
463			}
464			value := *sm.Value
465			if math.IsNaN(value) || math.IsInf(value, 0) {
466				return nil, "invalid_metrics" // encoding/json already rejects NaN/Inf tokens
467			}
468			if typ == "counter" && value < 0 {
469				return nil, "invalid_metrics"
470			}
471	
472			var buckets []float64
473			if typ == "histogram" {
474				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
475					return nil, "invalid_metrics"
476				}
477				buckets = append([]float64(nil), (*sm.Buckets)...)
478			} else if sm.Buckets != nil {
479				return nil, "invalid_metrics" // buckets only valid on histograms
480			}
481	
482			// The timestamp is optional; every sample without one shares the
483			// request's receive instant.
484			ts := receivedAt
485			if sm.Timestamp != nil {
486				parsed, err := time.Parse(time.RFC3339Nano, *sm.Timestamp)
487				if err != nil {
488					return nil, "invalid_metrics"
489				}
490				ts = parsed
491			}
492			if ts.Before(receivedAt.Add(-metricRetention)) || ts.After(receivedAt.Add(maxFutureSkew)) {
493				return nil, "metric_timestamp_out_of_range"
494			}
495	
496			batch = append(batch, validatedSample{
497				key:     seriesKey(name, labels),
498				name:    name,
499				typ:     typ,
500				labels:  copyLabels(labels),
501				value:   value,
502				buckets: buckets,
503				ts:      ts,
504			})
505		}
506		return batch, ""
507	}
508	
509	func validBuckets(buckets []float64) bool {
510		if len(buckets) == 0 {
511			return false
512		}
513		prev := math.Inf(-1)
514		for _, b := range buckets {
515			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
516				return false
517			}
518			prev = b
519		}
520		return true
521	}
522	
523	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
524	// values and non-object payloads for struct targets.
525	func strictDecode(data []byte, target any) bool {
526		dec := json.NewDecoder(bytes.NewReader(data))
527		dec.DisallowUnknownFields()
528		if err := dec.Decode(target); err != nil {
529			return false
530		}
531		var extra json.RawMessage
532		if err := dec.Decode(&extra); err != io.EOF {
533			return false
534		}
535		return true
536	}
537	
538	func handleMetricsGet(w http.ResponseWriter, r *http.Request) {
539		store := tenantStore(r)
540		values, err := url.ParseQuery(r.URL.RawQuery)
541		if err != nil {
542			writeAPIError(w, "invalid_query", http.StatusBadRequest)
543			return
544		}
545	
546		names := values["name"]
547		if len(names) == 0 || !identPattern.MatchString(names[0]) {
548			writeAPIError(w, "invalid_query", http.StatusBadRequest)
549			return
550		}
551	
552		selector := make(map[string]string)
553		for key, vals := range values {
554			if !strings.HasPrefix(key, "label.") {
555				continue
556			}
557			labelKey := strings.TrimPrefix(key, "label.")
558			if !identPattern.MatchString(labelKey) {
559				writeAPIError(w, "invalid_query", http.StatusBadRequest)
560				return
561			}
562			for _, v := range vals[1:] {
563				if v != vals[0] {
564					writeAPIError(w, "invalid_query", http.StatusBadRequest)
565					return
566				}
567			}
568			selector[labelKey] = vals[0]
569		}
