12		"net/http"
13		"net/url"
14		"sort"
15		"strconv"
16		"strings"
17		"time"
18	)
19	
20	const (
21		logsPath = "/api/v1/logs"
22	
23		maxLogBatch        = 500
24		maxLogIDsPerTenant = 10000
25		maxLogIDLen        = 128
26		defaultLogLimit    = 100
27		maxLogLimit        = 200
28	)
29	
30	var logLevels = map[string]bool{
31		"debug": true,
32		"info":  true,
33		"warn":  true,
34		"error": true,
35	}
36	
37	// logEntry is one committed log record. Entries are immutable once stored;
38	// only eviction removes them.
39	type logEntry struct {
40		id        string
41		timestamp time.Time
42		level     string
43		message   string
44		labels    map[string]string
45		traceID   string // "" when absent
46		seq       int64  // commit sequence, assigned at insert
47	}
48	
49	// sameContent reports whether two entries with the same id carry the same
50	// timestamp instant and the same remaining content, making the later one a
51	// replay rather than a conflict.
52	func (e *logEntry) sameContent(other *logEntry) bool {
53		return e.id == other.id &&
54			e.timestamp.Equal(other.timestamp) &&
55			e.level == other.level &&
56			e.message == other.message &&
57			e.traceID == other.traceID &&
58			maps.Equal(e.labels, other.labels)
59	}
60	
61	// checkAndApplyLogs validates the batch against committed state (and against
62	// itself) and then commits it in array order. A false ok signals a content
63	// conflict on a repeated id; in that case no state is mutated. Replays —
64	// repeats of an id with identical content — are counted but do not mutate
65	// state or refresh eviction order. Conflict and replay detection always runs
66	// before sampling: only ids not yet retained are subject to the tenant's
67	// sampling policy, and dropped entries leave no trace — they take no id, no
68	// capacity and no commit sequence. sampling reports whether the policy in
69	// effect had any rate below 1, so the response can carry sampled_out.
70	func (s *metricStore) checkAndApplyLogs(batch []*logEntry) (accepted, replayed, sampledOutN int, sampling, ok bool) {
71		s.mu.Lock()
72		defer s.mu.Unlock()
73	
74		// First pass: conflict detection against committed entries and earlier
75		// entries in the same batch.
76		seen := make(map[string]*logEntry, len(batch))
77		for _, e := range batch {
78			if prev, dup := seen[e.id]; dup {
79				if !prev.sameContent(e) {
80					return 0, 0, 0, false, false
81				}
82				continue
83			}
84			if existing, committed := s.logs[e.id]; committed && !existing.sameContent(e) {
85				return 0, 0, 0, false, false
86			}
87			seen[e.id] = e
88		}
89	
90		// Second pass: commit in array order, then evict the oldest ids until
91		// the tenant is back within the retention bound. Entries without a
92		// trace id sample on their own id at log_rate; traced entries sample on
93		// the trace id at trace_rate, staying consistent with the trace's spans.
94		policy := s.sampling
95		sampling = policy.active()
96		for _, e := range batch {
97			if _, exists := s.logs[e.id]; exists {
98				replayed++
99				continue
100			}
101			identity, rate := e.id, policy.LogRate
102			if e.traceID != "" {
103				identity, rate = e.traceID, policy.TraceRate
104			}
105			if sampledOut(identity, rate) {
106				sampledOutN++
107				continue
108			}
109			s.logSeq++
110			e.seq = s.logSeq
111			s.logs[e.id] = e
112			s.logOrder = append(s.logOrder, e.id)
113			accepted++
114		}
115		if len(s.logOrder) > maxLogIDsPerTenant {
116			excess := len(s.logOrder) - maxLogIDsPerTenant
117			for _, id := range s.logOrder[:excess] {
118				delete(s.logs, id)
119			}
120			s.logOrder = append([]string(nil), s.logOrder[excess:]...)
121		}
122		return accepted, replayed, sampledOutN, sampling, true
123	}
124	
125	// logFilter is the immutable condition set of a log query. A nil entry in
126	// hasStart/hasEnd marks an open bound.
127	type logFilter struct {
128		start    time.Time
129		hasStart bool
130		end      time.Time
131		hasEnd   bool
132		level    string
133		traceID  string
134		q        string
135		labels   map[string]string
136	}
137	
138	func (f *logFilter) matches(e *logEntry) bool {
139		if f.hasStart && e.timestamp.Before(f.start) {
140			return false
141		}
142		if f.hasEnd && !e.timestamp.Before(f.end) {
143			return false
144		}
145		if f.level != "" && e.level != f.level {
146			return false
147		}
148		if f.traceID != "" && e.traceID != f.traceID {
149			return false
150		}
151		if f.q != "" && !strings.Contains(e.message, f.q) {
152			return false
153		}
154		for k, v := range f.labels {
155			got, ok := e.labels[k]
156			if !ok || got != v {
157				return false
158			}
159		}
160		return true
161	}
162	
163	// queryLogs returns the page of entries matching the filter within the
164	// snapshot (entries with seq <= snapshotSeq), strictly after the position
165	// (afterTS, afterID) in result order, plus whether more entries remain.
166	// Result order is timestamp descending, id ascending within one instant.
167	func (s *metricStore) queryLogs(f *logFilter, snapshotSeq int64, afterTS time.Time, afterID string, hasAfter bool, limit int) ([]*logEntry, bool) {
168		s.mu.RLock()
169		defer s.mu.RUnlock()
170	
171		matched := make([]*logEntry, 0)
172		for _, e := range s.logs {
173			if e.seq > snapshotSeq {
174				continue // written after the snapshot anchor; never mixes in
175			}
176			if !f.matches(e) {
177				continue
178			}
179			if hasAfter && !comesAfter(e, afterTS, afterID) {
180				continue
181			}
182			matched = append(matched, e)
183		}
184		sort.Slice(matched, func(i, j int) bool {
185			a, b := matched[i], matched[j]
186			if !a.timestamp.Equal(b.timestamp) {
187				return a.timestamp.After(b.timestamp)
188			}
189			return a.id < b.id
190		})
191	
192		more := len(matched) > limit
193		if more {
194			matched = matched[:limit]
195		}
196		return matched, more
197	}
198	
199	// comesAfter reports whether e sorts strictly after the position (ts, id) in
200	// result order.
201	func comesAfter(e *logEntry, ts time.Time, id string) bool {
202		if e.timestamp.Equal(ts) {
203			return e.id > id
204		}
205		return e.timestamp.Before(ts)
206	}
207	
208	// ---- JSON wire shapes ------------------------------------------------------
209	
210	type logsEnvelope struct {
211		Entries *[]json.RawMessage `json:"entries"`
212	}
213	
214	type rawLogEntry struct {
215		ID        *string            `json:"id"`
216		Timestamp *string            `json:"timestamp"`
217		Level     *string            `json:"level"`
218		Message   *string            `json:"message"`
219		Labels    *map[string]string `json:"labels"`
220		TraceID   *string            `json:"trace_id"`
221	}
222	
223	type logEntryJSON struct {
224		ID        string            `json:"id"`
225		Timestamp string            `json:"timestamp"`
226		Level     string            `json:"level"`
227		Message   string            `json:"message"`
228		Labels    map[string]string `json:"labels"`
229		TraceID   string            `json:"trace_id,omitempty"`
230	}
231	
232	func (e *logEntry) wireJSON() logEntryJSON {
233		return logEntryJSON{
234			ID:        e.id,
235			Timestamp: e.timestamp.UTC().Format(time.RFC3339Nano),
236			Level:     e.level,
237			Message:   e.message,
238			Labels:    copyLabels(e.labels),
239			TraceID:   e.traceID,
240		}
241	}
242	
243	// decodeLogBatch performs every format and value check. It never returns a
244	// partially validated batch.
245	func decodeLogBatch(body []byte) ([]*logEntry, bool) {
246		var env logsEnvelope
247		if !strictDecode(body, &env) || env.Entries == nil || len(*env.Entries) == 0 || len(*env.Entries) > maxLogBatch {
248			return nil, false
249		}
250	
251		batch := make([]*logEntry, 0, len(*env.Entries))
252		for _, raw := range *env.Entries {
253			var re rawLogEntry
254			if !strictDecode(raw, &re) {
255				return nil, false
256			}
257			if re.ID == nil || re.Timestamp == nil || re.Level == nil || re.Message == nil || re.Labels == nil {
258				return nil, false
259			}
260			id := *re.ID
261			if !validLogID(id) {
262				return nil, false
263			}
264			ts, err := time.Parse(time.RFC3339Nano, *re.Timestamp)
265			if err != nil {
266				return nil, false
267			}
268			level := *re.Level
269			if !logLevels[level] {
270				return nil, false
271			}
272			labels := *re.Labels
273			if labels == nil {
274				return nil, false // explicit null labels
275			}
276			for k := range labels {
277				if !identPattern.MatchString(k) {
278					return nil, false
279				}
280			}
281			traceID := ""
282			if re.TraceID != nil {
283				traceID = *re.TraceID
284				if !validTraceID(traceID) {
285					return nil, false
286				}
287			}
288			batch = append(batch, &logEntry{
289				id:        id,
290				timestamp: ts,
291				level:     level,
292				message:   *re.Message,
293				labels:    copyLabels(labels),
294				traceID:   traceID,
295			})
296		}
297		return batch, true
298	}
299	
300	// validLogID reports whether id is 1-128 printable ASCII characters.
301	func validLogID(id string) bool {
302		if len(id) == 0 || len(id) > maxLogIDLen {
303			return false
304		}
305		for i := 0; i < len(id); i++ {
306			if id[i] < 0x20 || id[i] > 0x7e {
307				return false
308			}
309		}
310		return true
311	}
312	
313	func validTraceID(id string) bool {
314		if len(id) != 32 {
315			return false
316		}
317		for i := 0; i < len(id); i++ {
318			c := id[i]
319			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
320				return false
321			}
322		}
323		return true
324	}
325	
326	// ---- cursor ----------------------------------------------------------------
327	
328	// logCursor pins the first request's conditions, page size and snapshot
329	// upper bound, plus the position the next page continues from.
330	type logCursor struct {
331		V        int               `json:"v"`
332		Tenant   string            `json:"tenant"`
333		Start    string            `json:"start,omitempty"`
334		End      string            `json:"end,omitempty"`
335		Level    string            `json:"level,omitempty"`
336		TraceID  string            `json:"trace_id,omitempty"`
337		Q        string            `json:"q,omitempty"`
338		Labels   map[string]string `json:"labels,omitempty"`
339		Limit    int               `json:"limit"`
340		Snapshot int64             `json:"snapshot"`
341		LastTS   string            `json:"last_ts"`
342		LastID   string            `json:"last_id"`
343	}
344	
345	// cursorKey signs cursors so tampered or foreign tokens are rejected as
346	// invalid_cursor. Log state is process-local, so a random per-process key is
347	// sufficient and cursors are not expected to survive restarts.
348	var cursorKey = func() []byte {
349		key := make([]byte, 32)
350		if _, err := rand.Read(key); err != nil {
351			panic(err)
352		}
353		return key
354	}()
355	
356	func encodeCursor(c *logCursor) string {
357		payload, _ := json.Marshal(c)
358		mac := hmac.New(sha256.New, cursorKey)
359		mac.Write(payload)
360		return base64.RawURLEncoding.EncodeToString(payload) + "." +
361			base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
362	}
363	
364	// decodeCursor parses and validates a cursor token. The boolean is false for
365	// any malformed, tampered or otherwise unusable token.
366	func decodeCursor(token string) (*logCursor, bool) {
367		payloadPart, macPart, ok := strings.Cut(token, ".")
368		if !ok {
369			return nil, false
370		}
371		payload, err := base64.RawURLEncoding.DecodeString(payloadPart)
372		if err != nil {
373			return nil, false
374		}
375		wantMAC, err := base64.RawURLEncoding.DecodeString(macPart)
376		if err != nil {
377			return nil, false
378		}
379		mac := hmac.New(sha256.New, cursorKey)
380		mac.Write(payload)
381		if !hmac.Equal(mac.Sum(nil), wantMAC) {
382			return nil, false
383		}
384		var c logCursor
385		if !strictDecode(payload, &c) {
386			return nil, false
387		}
388		if c.V != 1 || c.Tenant == "" || c.Limit < 1 || c.Limit > maxLogLimit || c.Snapshot < 0 {
389			return nil, false
390		}
391		if c.Level != "" && !logLevels[c.Level] {
392			return nil, false
393		}
394		if c.TraceID != "" && !validTraceID(c.TraceID) {
395			return nil, false
396		}
397		for k := range c.Labels {
398			if !identPattern.MatchString(k) {
399				return nil, false
400			}
401		}
402		if c.Start != "" {
403			if _, err := time.Parse(time.RFC3339Nano, c.Start); err != nil {
404				return nil, false
405			}
406		}
407		if c.End != "" {
408			if _, err := time.Parse(time.RFC3339Nano, c.End); err != nil {
409				return nil, false
410			}
411		}
412		if _, err := time.Parse(time.RFC3339Nano, c.LastTS); err != nil {
413			return nil, false
414		}
415		if !validLogID(c.LastID) {
416			return nil, false
417		}
418		return &c, true
419	}
420	
421	// ---- HTTP handlers ---------------------------------------------------------
422	
423	func registerLogHandlers(mux *http.ServeMux) {
424		mux.HandleFunc(logsPath, func(w http.ResponseWriter, r *http.Request) {
425			switch r.Method {
426			case http.MethodGet:
427				handleLogsGet(w, r)
428			case http.MethodPost:
429				handleLogsPost(w, r)
430			default:
431				w.Header().Set("Allow", "GET, POST")
432				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
433			}
434		})
435	}
436	
437	func handleLogsPost(w http.ResponseWriter, r *http.Request) {
438		store := tenantStore(r)
439		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
440		if err != nil || mediaType != "application/json" {
441			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
442			return
443		}
444	
445		body, err := io.ReadAll(r.Body)
446		if err != nil {
447			writeAPIError(w, "invalid_logs", http.StatusBadRequest)
448			return
449		}
450	
451		batch, ok := decodeLogBatch(body)
452		if !ok {
453			writeAPIError(w, "invalid_logs", http.StatusBadRequest)
454			return
455		}
456	
457		accepted, replayed, sampledOutN, sampling, applied := store.checkAndApplyLogs(batch)
458		if !applied {
459			writeAPIError(w, "log_conflict", http.StatusConflict)
460			return
461		}
462	
463		resp := map[string]int{"accepted": accepted, "replayed": replayed}
464		if sampling {
465			resp["sampled_out"] = sampledOutN
466		}
467		writeJSON(w, http.StatusAccepted, resp)
468	}
469	
470	func handleLogsGet(w http.ResponseWriter, r *http.Request) {
471		store := tenantStore(r)
472		values, err := url.ParseQuery(r.URL.RawQuery)
473		if err != nil {
474			writeAPIError(w, "invalid_log_query", http.StatusBadRequest)
475			return
476		}
477	
478		if cursors, present := values["cursor"]; present {
479			// A follow-up request carries exactly one cursor and nothing else.
480			if len(values) != 1 || len(cursors) != 1 {
481				writeAPIError(w, "invalid_log_query", http.StatusBadRequest)
482				return
483			}
484			cursor, ok := decodeCursor(cursors[0])
485			if !ok || cursor.Tenant != tenantName(r) {
486				writeAPIError(w, "invalid_cursor", http.StatusBadRequest)
487				return
488			}
489			serveLogPage(w, store, cursor)
490			return
491		}
492	
493		filter, limit, ok := parseLogQuery(values)
494		if !ok {
495			writeAPIError(w, "invalid_log_query", http.StatusBadRequest)
496			return
497		}
498	
499		store.mu.RLock()
500		snapshot := store.logSeq
501		store.mu.RUnlock()
502	
503		cursor := &logCursor{
504			V:        1,
505			Tenant:   tenantName(r),
506			Level:    filter.level,
507			TraceID:  filter.traceID,
508			Q:        filter.q,
509			Labels:   filter.labels,
510			Limit:    limit,
511			Snapshot: snapshot,
512		}
513		if filter.hasStart {
514			cursor.Start = filter.start.UTC().Format(time.RFC3339Nano)
515		}
516		if filter.hasEnd {
517			cursor.End = filter.end.UTC().Format(time.RFC3339Nano)
518		}
519		serveLogPage(w, store, cursor)
520	}
521	
522	// serveLogPage runs the paginated query described by cursor and writes the
523	// response, refreshing the cursor's position for the next page.
524	func serveLogPage(w http.ResponseWriter, store *metricStore, cursor *logCursor) {
525		filter := &logFilter{
526			level:   cursor.Level,
527			traceID: cursor.TraceID,
528			q:       cursor.Q,
529			labels:  cursor.Labels,
530		}
531		if cursor.Start != "" {
532			filter.start, _ = time.Parse(time.RFC3339Nano, cursor.Start)
533			filter.hasStart = true
534		}
535		if cursor.End != "" {
536			filter.end, _ = time.Parse(time.RFC3339Nano, cursor.End)
537			filter.hasEnd = true
538		}
539	
540		var afterTS time.Time
541		hasAfter := cursor.LastTS != ""
542		if hasAfter {
543			afterTS, _ = time.Parse(time.RFC3339Nano, cursor.LastTS)
544		}
545	
546		page, more := store.queryLogs(filter, cursor.Snapshot, afterTS, cursor.LastID, hasAfter, cursor.Limit)
547	
548		entries := make([]logEntryJSON, 0, len(page))
549		for _, e := range page {
550			entries = append(entries, e.wireJSON())
551		}
552	
553		var nextCursor *string
554		if more {
555			last := page[len(page)-1]
556			cursor.LastTS = last.timestamp.UTC().Format(time.RFC3339Nano)
557			cursor.LastID = last.id
558			token := encodeCursor(cursor)
559			nextCursor = &token
560		}
561	
562		writeJSON(w, http.StatusOK, map[string]any{"entries": entries, "next_cursor": nextCursor})
563	}
564	
565	// parseLogQuery validates the first-request query parameters and builds the
566	// filter. Only the documented parameter vocabulary is accepted.
567	func parseLogQuery(values url.Values) (*logFilter, int, bool) {
568		filter := &logFilter{labels: map[string]string{}}
569		limit := defaultLogLimit
570	
571		for key, vals := range values {
572			if len(vals) == 0 {
573				return nil, 0, false
574			}
575			// A repeated parameter is accepted only when every value agrees.
576			for _, v := range vals[1:] {
577				if v != vals[0] {
578					return nil, 0, false
579				}
580			}
581			value := vals[0]
582			switch {
583			case key == "start":
584				ts, err := time.Parse(time.RFC3339Nano, value)
585				if err != nil {
586					return nil, 0, false
587				}
588				filter.start, filter.hasStart = ts, true
589			case key == "end":
590				ts, err := time.Parse(time.RFC3339Nano, value)
591				if err != nil {
592					return nil, 0, false
593				}
594				filter.end, filter.hasEnd = ts, true
595			case key == "level":
596				if !logLevels[value] {
597					return nil, 0, false
598				}
599				filter.level = value
600			case key == "trace_id":
601				if !validTraceID(value) {
602					return nil, 0, false
603				}
604				filter.traceID = value
605			case key == "q":
606				filter.q = value
607			case key == "limit":
608				n, err := strconv.Atoi(value)
609				if err != nil || n < 1 || n > maxLogLimit {
610					return nil, 0, false
611				}
612				limit = n
613			case strings.HasPrefix(key, "label."):
614				labelKey := strings.TrimPrefix(key, "label.")
615				if !identPattern.MatchString(labelKey) {
616					return nil, 0, false
617				}
618				filter.labels[labelKey] = value
619			default:
620				return nil, 0, false
621			}
622		}
623		return filter, limit, true
624	}
